  function show(view){ $$('.view').forEach(el=>el.classList.toggle('active',el.id===view)); $$('.nav-link').forEach(el=>el.classList.toggle('active',el.dataset.view===view)); $('#page-title').textContent=titles[view]; window.scrollTo({top:0,behavior:'smooth'}); }
  function renderProgress(){ const done=workflow.filter(([key])=>complete(key)).length; $('#readiness-score').textContent=`${done} / ${workflow.length}`; $('#readiness-label').textContent=done===workflow.length?'Decision package ready':'Draft'; $('#progress-cards').innerHTML=workflow.map(([key,title,desc],i)=>`<article class="progress-card ${complete(key)?'complete':''}" data-open="${key}"><span class="step">${String(i+1).padStart(2,'0')}</span><h3>${title}</h3><p>${complete(key)?'Ready for review':desc}</p></article>`).join(''); $$('.progress-card').forEach(el=>el.addEventListener('click',()=>show(el.dataset.open))); }
  function unresolvedEvidence(){ return (data.evidence||[]).filter(r=>!['Validated','Resolved'].includes(r.state)); }
  function renderEvidence(){ const rows=data.evidence||[], unresolved=unresolvedEvidence(); const pill=$('#evidence-status'); pill.textContent=rows.length?`${unresolved.length} unresolved of ${rows.length}`:'No records'; pill.classList.toggle('complete',rows.length>0 && unresolved.length===0); $('#evidence-summary').textContent=rows.length?`${rows.length} structured evidence record${rows.length===1?'':'s'}; ${unresolved.length} require further review, validation, or resolution.`:'No evidence records have been added. Material assumptions remain visible but unresolved.'; $('#evidence-rows').innerHTML=rows.length?rows.map((r,i)=>`<tr><td>${esc(r.claim)}</td><td>${esc(r.area)}</td><td>${esc(r.recordType)}</td><td><span class="state ${esc(r.state).toLowerCase()}">${esc(r.state)}</span></td><td>${esc(r.source)}<br><small>${esc(r.sourceOwner)}</small></td><td>${esc(r.limitation||'None stated')}<br><small>${esc(r.reviewDate||'No review date')} / ${esc(r.confidence||'No confidence stated')}</small></td><td><button class="delete-evidence" data-evidence-index="${i}">Delete</button></td></tr>`).join(''):`<tr><td colspan="7" class="quiet-note">No evidence records yet.</td></tr>`; $$('.delete-evidence').forEach(btn=>btn.addEventListener('click',()=>{data.evidence.splice(+btn.dataset.evidenceIndex,1);persist();toast('Evidence record deleted.');})); }
  function renderBaseline(){ const b=calculatedBaseline(); $('#baseline-results').innerHTML=[['Current annual cost',money(b.current)],['Forecast net annual benefit',money(b.benefit)],['Payback period',b.payback===null?'Not available':`${number(b.payback*12)} months`],['First-year ROI',b.roi===null?'Not available':`${number(b.roi)}%`]].map(([label,value])=>`<article class="metric"><span>${label}</span><strong>${value}</strong></article>`).join(''); }
  function complianceScenario(activity, prefix){ const volume=+activity[`${prefix}Volume`]||0, hours=+activity[`${prefix}Hours`]||0, rate=+activity[`${prefix}Rate`]||0, external=+activity[`${prefix}External`]||0; return {volume,hours,rate,external,capacity:volume*hours,cost:(volume*hours*rate)+external}; }
  function complianceTotals(){ const activities=data.complianceCost?.activities||[]; return activities.reduce((total,activity)=>{ for(const scenario of ['baseline','pilot','target']){ const value=complianceScenario(activity,scenario); total[scenario].cost+=value.cost; total[scenario].capacity+=value.capacity; } return total; },{baseline:{cost:0,capacity:0},pilot:{cost:0,capacity:0},target:{cost:0,capacity:0}}); }
