  function rawAuthorityRecords(){ if(!Array.isArray(data.authorityEnvelopes) || !data.authorityEnvelopes.length){ if(Object.keys(data.authorityEnvelope||{}).length) data.authorityEnvelopes=[data.authorityEnvelope]; else data.authorityEnvelopes=[]; } return data.authorityEnvelopes; }
