  function renderAuthority(){ const a=selectedAuthority(), target=$('#authority-summary'); if(!target)return; refreshAuthoritySelector(); const completeEnvelope=complete('authority'); const pill=$('#authority-status'); pill.textContent=completeEnvelope?`${a.status} / ${a.decision}`:'Incomplete'; pill.classList.toggle('complete',completeEnvelope); if(!Object.keys(a).length){ target.innerHTML='<span class="quiet-note">No authority envelope recorded. Create one before treating a pilot or release as bounded by explicit authority.</span>'; return; } const unresolved=(a.relationships||[]).filter(x=>x.resolutionState!=='resolved'); const evidence=(a.evidenceRequirements||[])[0]||{}, lastDecision=(a.decisionHistory||[]).at(-1)||{}; target.innerHTML=`<span class="eyebrow">AUTHORITY SUMMARY / LOCAL DECISION RECORD</span><h3>${esc(a.id||'Unidentified authority envelope')}</h3><p><span class="label">AI system:</span> ${esc(a.aiSystem||'Not stated')} (${esc(a.aiSystemId||'No stable ID')}) &nbsp; <span class="label">Business capability:</span> ${esc(a.businessCapability||'Not stated')}</p><p><span class="label">Agent:</span> ${esc(a.agentId||'Not applicable / not identified')} &nbsp; <span class="label">Human authority:</span> ${esc(a.authorityOwner||'Not named')}</p><p><span class="label">Stored status / decision:</span> ${esc(a.status||'Not stated')} / ${esc(a.decision||'Not stated')}</p><p><span class="label">Effective / review:</span> ${esc(a.effectiveDate||'Not stated')} / ${esc(a.reviewDate||'Not stated')}</p><p><span class="label">Permitted actions:</span> ${esc(a.actions.map(x=>`${x.label} (${x.id})`).join('; ')||'Not stated')}</p><p><span class="label">Resources:</span> ${esc(a.resources.map(x=>`${x.label} (${x.id})`).join('; ')||'Not stated')}</p><p><span class="label">Evidence requirement / state:</span> ${esc(evidence.requirement||'Not stated')} / ${esc(evidence.assessmentState||'Not stated')} (${esc((evidence.actionIds||[]).join('; ')||'all permitted actions')})</p><p><span class="label">Acceptance / reviewer:</span> ${esc(evidence.acceptanceCriterion||'Not stated')} / ${esc(evidence.reviewer||'Not named')}</p><p><span class="label">Typed links:</span> ${(a.relationships||[]).length} (${unresolved.length} unresolved)</p><p><span class="label">Monitoring observations:</span> ${(a.monitoringObservations||[]).length} recorded; latest decision triggered by ${esc((lastDecision.triggeringObservationIds||[]).join('; ')||'no recorded observation')}</p><p><span class="label">Constrain / suspend / revoke:</span> ${esc(a.revocationConditions||'Not stated')}</p><p class="quiet-note">${esc(a.rationale||'No rationale recorded.')}</p>`; }
  function alternativeTemplate(alt={},index){ return `<article class="alternative" data-index="${index}"><div class="alternative-top"><strong>Alternative ${index+1}</strong><button type="button" class="remove-alternative">Remove</button></div><div class="form-grid"><label>Name<input required data-field="name" value="${esc(alt.name||'')}" placeholder="e.g., Simplify existing workflow"></label><label>Category<select required data-field="category"><option value="">Select</option>${['Do nothing','Retire or consolidate','Simplify','Integrate','Automate','Improve analytics','Introduce bounded AI'].map(v=>`<option ${alt.category===v?'selected':''}>${v}</option>`).join('')}</select></label><label>One-time cost ($)<input required type="number" min="0" step="0.01" data-field="cost" value="${esc(alt.cost||'')}"></label><label>Forecast annual benefit ($)<input required type="number" min="0" step="0.01" data-field="benefit" value="${esc(alt.benefit||'')}"></label><label>Feasibility (1-5)<input required type="number" min="1" max="5" step="1" data-field="feasibility" value="${esc(alt.feasibility||'')}"></label><label>Risk (1-5)<input required type="number" min="1" max="5" step="1" data-field="risk" value="${esc(alt.risk||'')}"></label><label class="full"><input type="radio" name="preferredAlternative" value="${index}" ${String(data.architecture.preferredAlternative)===String(index)?'checked':''}> Preferred alternative</label></div></article>`; }
  function renderAlternatives(){ const alts=data.architecture.alternatives?.length?data.architecture.alternatives:[{},{}]; $('#alternatives').innerHTML=alts.map(alternativeTemplate).join(''); $$('.remove-alternative').forEach(btn=>btn.addEventListener('click',()=>{ const item=btn.closest('.alternative'); const values=collectAlternatives(); values.splice(+item.dataset.index,1); data.architecture.alternatives=values; data.architecture.preferredAlternative=''; renderAlternatives(); })); }
