  function erirStatus(record){ if(record.record_type==='regulatory_source') return `${record.legal_status||'status not stated'} / ${record.review_status||'review not stated'}`; if(record.record_type==='obligation') return `${record.binding_status||'binding status not stated'} / ${record.review_status||'review not stated'}`; if(record.record_type==='applicability_assessment') return `${record.decision||'decision not stated'} / ${record.approval_status||'review not stated'}`; if(record.record_type==='control') return `${record.status||'status not stated'} / ${record.owner||'owner not stated'}`; if(record.record_type==='evidence') return `${record.assessment_result||'not assessed'} / collected ${record.collected_at||'not stated'}`; return 'Not stated'; }
  function erirCitation(record){ if(record.record_type==='regulatory_source') return `${record.title||record.id}${record.official_url?` — ${record.official_url}`:''}`; if(record.record_type==='obligation') return `${record.title||record.id}${record.citations?.[0]?.locator?` — ${record.citations[0].locator}`:''}`; return record.title||record.description||record.reasoning||record.id; }
  function erirRelationship(record){ if(record.record_type==='obligation') return `Source: ${record.source_id||'not stated'}`; if(record.record_type==='applicability_assessment') return `Obligation: ${record.obligation_id||'not stated'} / Asset: ${record.subject_asset_id||'not stated'}`; if(record.record_type==='control') return `Obligations: ${(record.obligation_ids||[]).join(', ')||'not stated'}`; if(record.record_type==='evidence') return `Control: ${record.control_id||'not stated'}`; return record._erir_path||'ERIR record'; }
   function renderRegulatory(records=[]){ const r=data.regulatory||{}, ids=regulatoryIds(), pill=$('#regulatory-status'), publicDemo=runtimeErirConfig().publicDemo; pill.textContent=ids.length?`${ids.length} linked IDs`:'No links'; pill.classList.toggle('complete',ids.length>0); const unresolved=r.unresolvedConditions||'No unresolved regulatory conditions recorded.'; const service=publicDemo?'configured ERIR read-only service':'local ERIR gateway'; $('#regulatory-summary').textContent=records.length?`${records.length} ERIR record${records.length===1?'':'s'} displayed read-only. Linked status: ${r.status||'not stated'}. Unresolved conditions: ${unresolved}`:ids.length?`Saved ${ids.length} ERIR record ID${ids.length===1?'':'s'}; load the ${service} to retrieve record status and citations. Unresolved conditions: ${unresolved}`:'No ERIR records linked.'; $('#regulatory-rows').innerHTML=records.length?records.map(record=>`<tr><td>${esc(record.id)}<br><small>${esc(record.record_type)}</small></td><td>${esc(erirStatus(record))}<br><small>${esc(record.reviewed_at||record.assessed_at||record.last_verified_at||'No review date recorded')}</small></td><td>${esc(erirCitation(record))}</td><td>${esc(erirRelationship(record))}</td></tr>`).join(''):`<tr><td colspan="4" class="quiet-note">${ids.length?`No linked ERIR record was returned. Check the ${service} and identifiers.`:`Connect the ${service} and load linked record IDs to display read-only traceability.`}</td></tr>`; }
  function buildErirHandoff(){ const r=data.regulatory||{}, o=data.opportunity||{}, risk=data.risk||{}, assetId=r.subjectAssetId, authority=authorityRecords()[0]; const records=[]; if(assetId){ records.push({record_type:'subject_profile',id:assetId,title:o.name||'ROI-EA decision context',facts:{opportunity:o.name||null,capability:o.capability||null,system_role:risk.systemRole||null,action_capability:risk.actionCapability||null,data_sensitivity:risk.dataSensitivity||null},profile_owner:o.sponsor||'Not assigned',updated_at:new Date().toISOString(),notes:'Draft context exported from ROI-Driven Enterprise Architect. ERIR human review remains required.'}); } const relationships=(authority?.relationships||[]).filter(x=>['regulatory_context','constrained_by_control','supported_by_evidence'].includes(x.relationshipType)).map(x=>({...x,provenance:'ROI-EA local authority reference; ERIR remains authoritative for the target record.'})); return {package_type:'erir_ea_handoff',contract_version:'1.1',generated_at:new Date().toISOString(),review_status:'draft',provenance:{source_application:'ROI-Driven Enterprise Architect MVP',local_record:true},references:{source_id:r.sourceId||null,obligation_id:r.obligationId||null,applicability_assessment_id:r.assessmentId||null,control_id:r.controlId||null,evidence_id:r.evidenceId||null,linked_review_date:r.reviewDate||null,linked_status:r.status||null,source_citation:r.citation||null,unresolved_conditions:r.unresolvedConditions||null},records,relationships}; }
   async function loadErirTrace(){ const r=data.regulatory||{}, ids=regulatoryIds(), base=resolveErirApiBase(r); if(!ids.length){toast('Save at least one ERIR record ID first.');return;} if(!base){ renderRegulatory(); toast('ERIR public-demo API is not configured. Saved ERIR IDs remain visible and unresolved.'); return; } try { const response=await fetch(erirTraceUrl(ids,r)); if(!response.ok) throw new Error(`ERIR API returned ${response.status}`); const result=await response.json(); renderRegulatory(result.records||[]); if(result.missing_ids?.length) toast(`ERIR did not return: ${result.missing_ids.join(', ')}`); else toast('Read-only ERIR traceability loaded.'); } catch(error){ renderRegulatory(); toast(`ERIR traceability unavailable; saved IDs remain unresolved: ${error.message}`); } }
